// ============================================
// 데이터 필터링 (쿼리 JSON 기반 범용 집계 엔진)
// ============================================

const meta = $('쿼리 정제').first().json;
const rows = $input.first().json.values ?? [];
const [header, ...dataRows] = rows;

// 열 인덱스 동적 매핑 (헤더 기준 — 시트 구조 변경에 견고)
const headerMap = Object.fromEntries(header.map((h, i) => [h, i]));
const idx = {
  주문일시: headerMap['주문일시'],
  점주명: headerMap['점주명'],
  상품명: headerMap['상품명'],
  옵션값: headerMap['옵션값'],
  수량: headerMap['수량'],
  단가: headerMap['단가']
};

// 헤더 누락 검증 (운영 안전장치)
const missingCols = Object.entries(idx)
  .filter(([_, v]) => v === undefined)
  .map(([k]) => k);
if (missingCols.length > 0) {
  throw new Error(`주문_RAW 시트에서 다음 컬럼을 찾을 수 없습니다: ${missingCols.join(', ')}`);
}

// 상품 표시 헬퍼 (상품명 + 옵션값)
const 상품표시 = (row) => {
  const 명 = row[idx.상품명] || '';
  const 옵 = row[idx.옵션값] || '';
  if (명 && 옵) return `${명} (${옵})`;
  return 명 || 옵 || '미상';
};

// ---------- 1. 필터링 ----------
const filterRow = (row, 필터) => {
  // 점주 필터
  if (필터.점주 && 필터.점주.length > 0) {
    if (!필터.점주.includes(row[idx.점주명])) return false;
  }

  // 기간 필터
  const 년월 = (row[idx.주문일시] || '').slice(0, 7);
  if (필터.기간시작 && 년월 < 필터.기간시작) return false;
  if (필터.기간종료 && 년월 > 필터.기간종료) return false;

  // 상품 키워드 필터
  if (필터.상품키워드 && 필터.상품키워드.length > 0) {
    const 상품전체 = `${row[idx.상품명] || ''} ${row[idx.옵션값] || ''}`;
    const 매칭 = 필터.상품키워드.some(k => 상품전체.includes(k));
    if (!매칭) return false;
  }

  return true;
};

// ---------- 2. 집계 함수 ----------
const 집계수행 = (rows, 스펙) => {
  const 그룹 = {};

  for (const row of rows) {
    // 그룹 키 생성
    const 키 = 스펙.그룹.map(g => {
      if (g === '점주명') return row[idx.점주명] || '미상';
      if (g === '상품명') return 상품표시(row);
      if (g === '년월') return (row[idx.주문일시] || '').slice(0, 7);
      return '';
    }).join(' | ');

    if (!키) continue;

    const 수량 = parseInt(row[idx.수량]) || 0;
    const 단가 = parseInt(row[idx.단가]) || 0;
    const 매출 = 수량 * 단가;

    if (!그룹[키]) 그룹[키] = { 매출: 0, 수량: 0, 주문수: 0 };
    그룹[키].매출 += 매출;
    그룹[키].수량 += 수량;
    그룹[키].주문수 += 1;
  }

  // 정렬
  let 엔트리 = Object.entries(그룹);
  if (스펙.정렬 === '매출내림차순') 엔트리.sort((a, b) => b[1].매출 - a[1].매출);
  else if (스펙.정렬 === '수량내림차순') 엔트리.sort((a, b) => b[1].수량 - a[1].수량);
  else if (스펙.정렬 === '년월오름차순') 엔트리.sort((a, b) => a[0].localeCompare(b[0]));

  // 상위 N
  if (스펙.상위N && 스펙.상위N > 0) {
    엔트리 = 엔트리.slice(0, 스펙.상위N);
  }

  return Object.fromEntries(엔트리);
};

// ---------- 3. 메인 실행 ----------
const 필터링된 = dataRows.filter(row => filterRow(row, meta.필터 ?? {}));

const 결과 = {
  기간: `${meta.필터?.기간시작 ?? '전체'} ~ ${meta.필터?.기간종료 ?? '전체'}`,
  점주필터: meta.필터?.점주 ?? '전체',
  필터링행수: 필터링된.length
};

// 각 집계 수행
for (const 스펙 of meta.집계 ?? []) {
  결과[스펙.이름] = 집계수행(필터링된, 스펙);
}

// 전체 총계 (항상 포함)
결과.전체총계 = {
  매출: 필터링된.reduce((s, r) => s + (parseInt(r[idx.수량]) || 0) * (parseInt(r[idx.단가]) || 0), 0),
  수량: 필터링된.reduce((s, r) => s + (parseInt(r[idx.수량]) || 0), 0),
  주문수: 필터링된.length
};

// ---------- 4. 비교 집계 (전월대비) ----------
if (meta.비교?.전월대비 && meta.필터?.기간시작) {
  const 전월 = (() => {
    const [y, m] = meta.필터.기간시작.split('-').map(Number);
    const d = new Date(y, m - 2, 1);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
  })();

  const 전월행 = dataRows.filter(row => {
    if (meta.필터.점주 && meta.필터.점주.length > 0) {
      if (!meta.필터.점주.includes(row[idx.점주명])) return false;
    }
    const 년월 = (row[idx.주문일시] || '').slice(0, 7);
    return 년월 === 전월;
  });

  결과.비교_전월 = {
    기간: 전월,
    매출: 전월행.reduce((s, r) => s + (parseInt(r[idx.수량]) || 0) * (parseInt(r[idx.단가]) || 0), 0),
    수량: 전월행.reduce((s, r) => s + (parseInt(r[idx.수량]) || 0), 0),
    주문수: 전월행.length
  };
}

// ---------- 5. 비교 집계 (전년동월대비) ----------
if (meta.비교?.전년동월대비 && meta.필터?.기간시작) {
  const 전년동월 = (() => {
    const [y, m] = meta.필터.기간시작.split('-').map(Number);
    return `${y - 1}-${String(m).padStart(2, '0')}`;
  })();

  const 전년행 = dataRows.filter(row => {
    if (meta.필터.점주 && meta.필터.점주.length > 0) {
      if (!meta.필터.점주.includes(row[idx.점주명])) return false;
    }
    const 년월 = (row[idx.주문일시] || '').slice(0, 7);
    return 년월 === 전년동월;
  });

  결과.비교_전년동월 = {
    기간: 전년동월,
    매출: 전년행.reduce((s, r) => s + (parseInt(r[idx.수량]) || 0) * (parseInt(r[idx.단가]) || 0), 0),
    수량: 전년행.reduce((s, r) => s + (parseInt(r[idx.수량]) || 0), 0),
    주문수: 전년행.length
  };
}

// ---------- 6. 최종 반환 ----------
return [{
  json: {
    ...meta,
    data: JSON.stringify(결과),
    dataSize: JSON.stringify(결과).length
  }
}];

const meta = $('데이터 필터링').first().json;
const raw = $('Report').first().json.output;
let parsed;
try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { 문서코드: 'RPT', 오류: 'JSON 파싱 실패' };
}
const 문서코드 = parsed.문서코드 ?? meta.문서코드;
const 카테고리 = parsed.카테고리 ?? meta.카테고리;
const 구분선 = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n';
const requests = [];
let currentIndex = 1;

const append = (text) => {
  requests.push({
    insertText: {
      text,
      endOfSegmentLocation: { segmentId: '' }
    }
  });
  currentIndex += text.length;
};

const appendHeading2 = (text) => {
  const startIdx = currentIndex;
  append(text);
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: startIdx, endIndex: startIdx + text.length - 1 },
      paragraphStyle: { namedStyleType: 'HEADING_4' },
      fields: 'namedStyleType'
    }
  });
};

// 헤더
append('AROMAFOREST\n');
append('\n');
append(`문서번호: ${meta.문서번호}\n`);
append(`생성일시: ${meta.생성일시}\n`);
append(`문서유형: ${문서코드 === 'RPT' ? '데이터분석' : '인사이트'} | 카테고리: ${카테고리}\n`);
append('\n');
append(구분선);

// AROMAFOREST 폰트 스타일
requests.push({
  updateTextStyle: {
    range: { startIndex: 1, endIndex: 13 },
    textStyle: { fontSize: { magnitude: 20, unit: 'PT' } },
    fields: 'fontSize'
  }
});

if (문서코드 === 'RPT') {
  // 01. 요약
  appendHeading2('01. 요약\n');
  for (const item of parsed.요약 ?? []) {
    append(`  ${item.키}: ${item.값}\n`);
  }

  // 02. 상세 데이터
  appendHeading2('02. 상세 데이터\n');

  // 🆕 동적으로 '상세데이터*' 키 모두 수집
  const tables = Object.keys(parsed)
    .filter(k => k.startsWith('상세데이터'))
    .sort()
    .map(k => parsed[k])
    .filter(Boolean);

  for (const table of tables) {
    append(`\n${table.제목}\n`);
    requests.push({
      insertTable: {
        rows: table.행들.length + 1,
        columns: table.컬럼.length,
        endOfSegmentLocation: { segmentId: '' }
      }
    });
    append('\n');
  }

  // 03. 인사이트 (표 이후라 index 추적 없이 삽입만)
  if (parsed.인사이트?.length > 0) {
    requests.push({ insertText: { text: '03. 인사이트\n', endOfSegmentLocation: { segmentId: '' } } });
    for (const item of parsed.인사이트) {
      requests.push({ insertText: { text: `  • ${item}\n`, endOfSegmentLocation: { segmentId: '' } } });
    }
  }

  requests.push({ insertText: { text: `${parsed.합계 ?? ''}\n`, endOfSegmentLocation: { segmentId: '' } } });
  requests.push({ insertText: { text: 구분선, endOfSegmentLocation: { segmentId: '' } } });
} else {
  appendHeading2('01. 핵심 요약\n');
  append(`  ${parsed.핵심요약 ?? ''}\n`);
  appendHeading2('02. 분석 근거\n');
  for (const item of parsed.분석근거 ?? []) {
    append(`  • ${item}\n`);
  }
  appendHeading2('03. 참고 사항\n');
  for (const item of parsed.참고사항 ?? []) {
    append(`  • ${item}\n`);
  }
}

requests.push({ insertText: { text: '생성: 아로마포레스트 AI 분석 시스템\n', endOfSegmentLocation: { segmentId: '' } } });

const fullBody = JSON.stringify({ requests });
return [{
  json: {
    fullBody,
    parsedData: JSON.stringify(parsed),
    문서번호: meta.문서번호,
    문서코드,
    카테고리
  }
}];

// 파싱 AI 출력 정제
const raw = $input.first().json.output;
let query;
try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  query = JSON.parse(cleaned);
} catch(e) {
  query = {
    문서코드: 'RPT',
    카테고리: '매출',
    필터: { 점주: null, 기간시작: null, 기간종료: null, 상품키워드: null },
    집계: [],
    비교: { 전월대비: false, 전년동월대비: false },
    오류: 'AI 출력 파싱 실패: ' + e.message
  };
}

// 문서 메타 생성
const now = new Date();
const 생성일시 = now.toISOString().slice(0, 16).replace('T', ' ');
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const timeStr = now.toTimeString().slice(0, 8).replace(/:/g, '');  // HHmmss
const 문서번호 = `${query.문서코드}-${dateStr}-${timeStr}`;

// 원본 질문 가져오기 (Chat Trigger 노드 이름 확인 필요)
const question = $('When Executed by Another Workflow').first().json.original_query ?? '';

return [{
  json: {
    question,
    문서번호,
    생성일시,
    ...query
  }
}];

